  assert.equal(
    pickupDeadline(hold({ id: 'h', member: ADA, placedOn: '2026-11-01', readyOn: '2026-11-19' })),
    '2026-11-26',
  );
  assert.equal(
    pickupDeadline(hold({ id: 'h', member: ADA, placedOn: '2026-11-01', readyOn: '2026-11-15' })),
    '2026-11-23',
  );
});

